"use strict";

// Evaluation order for constraints in one scene.
//
// A constraint reads its target's world position and its own world position,
// and it writes the constrained object's local rotation. The rotation of an
// object never moves that object, but it moves all of its descendants. So a
// constraint on A depends on every constrained strict ancestor of A and on
// every constrained strict ancestor of A's target. An object tracking its own
// descendant depends on itself.
//
// orderConstraints() returns the constraints in a valid order and the set of
// constraints that take part in a cycle. Cyclic constraints are skipped; the
// rest are still evaluated (with the skipped ones left unconstrained).

// nodes: [{ key, deps: [key, ...] }] in authored (depth-first) order.
function orderConstraints(nodes) {
  const byKey = new Map();
  for (const node of nodes) byKey.set(node.key, node);
  const cyclic = findCyclicKeys(nodes, byKey);

  const order = [];
  const state = new Map(); // key -> 1 visiting, 2 done
  function visit(key) {
    if (state.get(key) === 2 || cyclic.has(key)) return;
    state.set(key, 1);
    const node = byKey.get(key);
    for (const dep of node.deps) {
      if (byKey.has(dep) && !cyclic.has(dep) && state.get(dep) !== 1) visit(dep);
    }
    state.set(key, 2);
    order.push(key);
  }
  for (const node of nodes) visit(node.key);
  return { order, cyclic };
}

// Tarjan's strongly connected components, iterative so deep hierarchies
// cannot overflow the stack. A component is cyclic when it has more than one
// member or its single member depends on itself.
function findCyclicKeys(nodes, byKey) {
  let index = 0;
  const indices = new Map();
  const lowlink = new Map();
  const onStack = new Set();
  const stack = [];
  const cyclic = new Set();

  for (const root of nodes) {
    if (indices.has(root.key)) continue;
    const work = [{ key: root.key, next: 0 }];
    indices.set(root.key, index);
    lowlink.set(root.key, index);
    index += 1;
    stack.push(root.key);
    onStack.add(root.key);
    while (work.length > 0) {
      const frame = work[work.length - 1];
      const deps = byKey.get(frame.key).deps.filter((dep) => byKey.has(dep));
      if (frame.next < deps.length) {
        const dep = deps[frame.next];
        frame.next += 1;
        if (!indices.has(dep)) {
          indices.set(dep, index);
          lowlink.set(dep, index);
          index += 1;
          stack.push(dep);
          onStack.add(dep);
          work.push({ key: dep, next: 0 });
        } else if (onStack.has(dep)) {
          lowlink.set(frame.key, Math.min(lowlink.get(frame.key), indices.get(dep)));
        }
        continue;
      }
      work.pop();
      if (work.length > 0) {
        const parent = work[work.length - 1].key;
        lowlink.set(parent, Math.min(lowlink.get(parent), lowlink.get(frame.key)));
      }
      if (lowlink.get(frame.key) === indices.get(frame.key)) {
        const component = [];
        let member;
        do {
          member = stack.pop();
          onStack.delete(member);
          component.push(member);
        } while (member !== frame.key);
        const selfLoop = component.length === 1 && byKey.get(member).deps.includes(member);
        if (component.length > 1 || selfLoop) {
          for (const key of component) cyclic.add(key);
        }
      }
    }
  }
  return cyclic;
}

// Dependencies of one constraint, given parent lookups.
//   parentOf(object) -> parent object or null
//   isConstrained(object) -> boolean
function constraintDependencies(object, target, parentOf, isConstrained) {
  const deps = new Set();
  // Direct target edges also reject reciprocal/chained tracking, even when
  // the objects are siblings and their origins would not move.
  if (target && isConstrained(target)) deps.add(target);
  for (const start of [object, target]) {
    let current = start ? parentOf(start) : null;
    let guard = 0;
    while (current && guard < 10000) {
      if (isConstrained(current)) deps.add(current);
      current = parentOf(current);
      guard += 1;
    }
  }
  return Array.from(deps);
}

function isAncestor(candidate, object, parentOf) {
  let current = object ? parentOf(object) : null;
  let guard = 0;
  while (current && guard < 10000) {
    if (current === candidate) return true;
    current = parentOf(current);
    guard += 1;
  }
  return false;
}

module.exports = { orderConstraints, findCyclicKeys, constraintDependencies, isAncestor };

"use strict";

// Relationship line: while a constrained object is selected in the editor,
// a thin dashed line joins it to its target. The line lives beside CM3's own
// selection helpers (BoxHelper, CameraHelper, light helpers): in the editor
// viewport's helper group, on Three layer 1. Scene cameras render layer 0
// only, so the line never appears in the preview output or in renders; it is
// visible in the 3D edit view, where CM3 draws its helpers.

const LINE_COLOR = 0x8ab4ff;
const DASH_SIZE = 2;
const GAP_SIZE = 1.5;

function installOverlay(options) {
  const PZ = options.PZ;
  const THREE = options.THREE;
  const store = options.store;
  const evaluator = options.evaluator;
  const prototype = PZ.ui?.viewport?.prototype;
  if (!prototype || typeof prototype._render !== "function" || !THREE.LineDashedMaterial) {
    return () => {};
  }
  const lines = new Map(); // viewport -> { line, object }
  const start = new THREE.Vector3();
  const end = new THREE.Vector3();

  function removeLine(viewport) {
    const entry = lines.get(viewport);
    if (!entry) return;
    lines.delete(viewport);
    const line = entry.line;
    line.parent?.remove(line);
    line.geometry.dispose();
    line.material.dispose();
  }

  function createLine(object) {
    const geometry = new THREE.BufferGeometry();
    geometry.addAttribute("position", new THREE.BufferAttribute(new Float32Array(6), 3));
    geometry.addAttribute("lineDistance", new THREE.BufferAttribute(new Float32Array(2), 1));
    const material = new THREE.LineDashedMaterial({
      color: LINE_COLOR,
      dashSize: DASH_SIZE,
      gapSize: GAP_SIZE,
      depthTest: false,
      depthWrite: false,
      transparent: true,
      opacity: 0.9,
    });
    const line = new THREE.Line(geometry, material);
    line.layers.set(1);
    line.frustumCulled = false;
    line.renderOrder = 1000;
    line.userData.zoidiumConstraintLine = true;
    line.onBeforeRender = function () {
      const scene = evaluator.sceneOf(object, PZ);
      const target = scene && object.threeObj ? evaluator.resolveTarget(object, scene) : null;
      const position = geometry.attributes.position;
      const distance = geometry.attributes.lineDistance;
      if (target && target.threeObj && object.parent) {
        start.setFromMatrixPosition(object.threeObj.matrixWorld);
        end.setFromMatrixPosition(target.threeObj.matrixWorld);
        if (line.parent) {
          // The helper group is a child of the scene; keep world coordinates.
          const inverse = new THREE.Matrix4().getInverse(line.parent.matrixWorld);
          start.applyMatrix4(inverse);
          end.applyMatrix4(inverse);
        }
      } else {
        start.set(0, 0, 0);
        end.set(0, 0, 0);
      }
      position.setXYZ(0, start.x, start.y, start.z);
      position.setXYZ(1, end.x, end.y, end.z);
      distance.setX(0, 0);
      distance.setX(1, start.distanceTo(end));
      position.needsUpdate = true;
      distance.needsUpdate = true;
    };
    return line;
  }

  function selectedObject(viewport) {
    const objects = viewport.helper3d?.objects;
    const selected = objects && objects.length === 1 ? objects[0] : null;
    if (!selected || !store.isAttached(selected) || store.classify(selected) === "none") return null;
    return store.readTarget(selected) ? selected : null;
  }

  // The viewport binds its render loop at construction, but calls _render
  // through the prototype on every animation frame.
  function syncLine(viewport) {
    const selected = viewport.threeObj ? selectedObject(viewport) : null;
    const entry = lines.get(viewport);
    if (entry && (entry.object !== selected || entry.line.parent !== viewport.threeObj)) removeLine(viewport);
    if (!selected || lines.has(viewport)) return;
    const line = createLine(selected);
    viewport.threeObj.add(line);
    lines.set(viewport, { line, object: selected });
  }

  const original = prototype._render;
  const patched = function renderWithConstraintLine() {
    try {
      syncLine(this);
    } catch (error) {
      if (!reported) {
        reported = true;
        console.warn("[Zoidium] Constraints: could not draw the relationship line.", error);
      }
    }
    return original.apply(this, arguments);
  };
  let reported = false;
  prototype._render = patched;

  return function disposeOverlay() {
    if (prototype._render === patched) prototype._render = original;
    for (const viewport of Array.from(lines.keys())) removeLine(viewport);
  };
}

module.exports = { installOverlay };

